/**
 * Prometheus' shade: every line the guide can speak, what triggers it, and when it
 * still makes sense. Pure data plus pure helpers (no World, DOM, timers or
 * packages): the asset manifest, the GuideSystem, the ToastSystem, the dev-only
 * voice-prep page, scripts/voice-urls.mjs and tests/voice-lines.test.mjs import it.
 *
 * Voice clips are generated by Drawcall (@drawcall/generate). A clip's URL is a
 * content hash of its request ({text, voice, style}). The runtime never computes it:
 * `node scripts/voice-urls.mjs` writes every line's hash into voice-urls.ts (a static
 * module), and tests/voice-lines.test.mjs fails when that file no longer matches the
 * package's computation. Changing a line's text, the voice or the style changes its
 * hash, so the clip must be generated again (voice-prep.html). A line's `hint` is
 * subtitle-only and never part of the request.
 */
import type { GameEvent } from './bus.js';
import { BOLTS_PER_BUNDLE, SENTRY_STARTER_BOLTS } from './recipes.js';

/** The shade's voice. A deep, calm Gemini voice; the style prompt sets the delivery. */
export const VOICE = {
  voice: 'Charon',
  style: 'An ancient Titan speaking softly beside a campfire at night: warm, weathered and unhurried, '
    + 'with quiet gravity and kindness. Low and close to the listener, never theatrical.',
} as const;

/** Same origin rule as the package's dist/origin.js (ORIGIN is not exported). */
export const DRAWCALL_ORIGIN: string = (import.meta.env?.DEV && import.meta.env.VITE_DRAWCALL_GENERATE_URL) || 'https://generate.drawcall.ai';

/** Speaking pace used to estimate a line's length when its clip is missing. */
export const WORDS_PER_SECOND = 2.3;
/** Longest subtitle the panel holds comfortably. */
export const MAX_TEXT = 220;
/** Longest spoken line (estimated seconds). */
export const MAX_SECONDS = 12;
/** Drawcall prepares at most 32 requests per batch; voice-prep.html splits the lines into batches of this size. */
export const PREP_BATCH = 20;

/**
 * Combat discipline: while a live wolf is within `radius` m of the player, or for
 * `hurtQuiet` s after a bite, only lines of `priority` or more may start (death,
 * respawn, the beacon and the ending); a lower line that is speaking is cut.
 */
export const THREAT = { priority: 9, radius: 12, hurtQuiet: 6 } as const;

/**
 * State checks, evaluated by the GuideSystem against the live game when a line's
 * turn comes: `unless` retires a line whose lesson the player already learned;
 * `when` drops a line whose moment has passed (a later trigger may queue it again).
 */
export type GuideCondition =
  | 'fire-lit' // the campfire is burning
  | 'page-read' // any page has been read
  | 'stew-cooked' // a stew waits in the pot, or a meal was eaten
  | 'meal-eaten' // the 'eat-meal' objective is done
  | 'pot-half' // exactly one food waits in the pot, no stew yet
  | 'fed' // hunger is comfortable again
  | 'healed' // health is comfortable again
  | 'whole' // health is (nearly) full
  | 'day' // the day phase (not dusk, night or dawn)
  | 'night' // dusk, night or dawn
  | 'grabbed' // the player has taken hold of something this session
  | 'wolves-stirring' // the danger stage is 1 or more: the Hollow come at night
  | 'at-bench' // the player stands within reach of the crafting bench
  | 'at-camp' // the player is at camp (near the campfire and its pot)
  | 'bench-ready' // the bench bays hold a valid set, not yet struck
  | 'bench-wrong' // the bench bays hold three parts that make nothing
  | 'torch-lit' // the torch objective is done
  | 'sentry-built' // the sentry objective is done
  | 'sentry-dry'; // a deployed sentry has no bolts left

export type GuideLine = {
  /** Unique id; saved in GameState.guide once spoken. */
  readonly id: string;
  /**
   * Trigger keys (see triggersOf and POLLED_TRIGGERS), each optionally delayed:
   * 'crafted:torch', 'done:intro+6' (6 s after the intro finished).
   */
  readonly on: readonly string[];
  /** The spoken words (and the subtitle). World verbs only: no controller parts. */
  readonly text: string;
  /** Subtitle-only control hint shown under the words (button names); never spoken. */
  readonly hint?: string;
  /** Higher speaks first when several lines wait. 10 = openers and the farewell. */
  readonly priority: number;
  /** Dropped and retired for the journey if this holds when its turn comes. */
  readonly unless?: GuideCondition;
  /** Every condition must hold when its turn comes, or the line is dropped (not retired). */
  readonly when?: readonly GuideCondition[];
  /**
   * Toasts this line says first: while it waits or speaks, a matching toast is
   * suppressed (shown after all if the line is dropped). Later toasts, once the line
   * was heard, show as usual. Pattern: 'key:<ToastSystem key>' or text contained in
   * the toast's title or body.
   */
  readonly covers?: readonly string[];
  /** Toasts held back until this line has spoken, then shown (same patterns). */
  readonly defers?: readonly string[];
  /** Speaks on every trigger (each session) instead of once per journey; never saved. */
  readonly repeat?: boolean;
  /** Speaks after the ending (every other line is dropped once the valley is warm). */
  readonly finale?: boolean;
  /** Seconds a queued line may wait before it is dropped as stale (default DEFAULT_TTL, at most MAX_TTL). */
  readonly ttl?: number;
};

/** Context lines go stale quickly; story beats set their own ttl. */
export const DEFAULT_TTL = 20;
/** No line waits longer than this, whatever its ttl. */
export const MAX_TTL = 180;

const NUMBER_WORDS = ['no', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten', 'eleven', 'twelve'];
/** 6 → 'six' (spoken numbers read and sound better than digits). */
export const numberWord = (n: number): string => NUMBER_WORDS[n] ?? String(n);

