/**
 * Trigger keys the GuideSystem raises by watching state (not from a bus event):
 * 'beacon-cold' (a lit torch held in the beacon before page 5 is read) and
 * 'beacon-slip' (the beacon's progress falling after it passed BEACON_SLIP_FROM).
 */
export const POLLED_TRIGGERS = ['hand-near', 'pot-full', 'hunger-low', 'health-low', 'sleep-ready', 'beacon-cold', 'beacon-slip'] as const;
/** The beacon-slip line waits until the hold has got this far (Beacon.progress). */
export const BEACON_SLIP_FROM = 0.25;

/** Thresholds for the polled triggers and the stale checks. */
export const GUIDE_THRESHOLDS = {
  hungerLow: 25, fed: 40,
  healthLow: 30, healed: 45, whole: 95,
  /** A hand this close (m) to a loose item counts as reaching for it. */
  handNear: 0.28,
  /** Within this distance (m) of the bench the player can act on a bench line. */
  benchReach: 3.5,
  /** Within this distance (m) of the campfire the player is at camp (the pot lines). */
  campReach: 10,
} as const;

/** Wood that chopping yields; its 'harvest' events are covered by the chop line. */
const WOOD = new Set(['log', 'stick', 'plank', 'deadwood']);
const WOLF_CUES = new Set(['howl', 'spawn', 'stalk', 'growl', 'bite']);

/**
 * Bus event → trigger keys (written into `out`, which is cleared first). Pure:
 * the GuideSystem calls it for every event and looks the keys up in TRIGGERS.
 */
export function triggersOf(event: GameEvent, out: string[] = []): string[] {
  out.length = 0;
  switch (event.type) {
    case 'journey-begin': out.push(event.resumed ? 'journey:resumed' : 'journey:new'); break;
    case 'grab': out.push('grab', `grab:${event.kind}`); break;
    case 'lighter': if (event.lit) out.push('lighter:on'); break;
    case 'fire-lit': out.push('fire-lit'); break;
    case 'fire-out': out.push('fire-out'); break;
    case 'ingredient': out.push('ingredient'); break;
    case 'stew-ready': out.push('stew-ready'); break;
    case 'eat': out.push('eat'); break;
    case 'well-fed': if (event.seconds > 0) out.push('well-fed'); break;
    case 'bench-set': out.push(event.valid ? 'bench:valid' : 'bench:invalid'); break;
    case 'crafted': out.push(`crafted:${event.product}`); break;
    case 'torch-lit': out.push('torch-lit'); break;
    case 'page': if (event.first) out.push('page', `page:${event.index}`); break;
    case 'chop': out.push('chop'); break;
    case 'harvest': if (!WOOD.has(event.kind)) out.push('harvest'); break;
    case 'pack': out.push(`pack:${event.state}`); break;
    case 'phase': out.push(`phase:${event.phase}`); break;
    case 'creature': if (event.species === 'wolf' && WOLF_CUES.has(event.cue)) out.push('wolf'); break;
    case 'hurt': out.push('hurt'); break;
    case 'respawn': out.push('respawn'); break;
    case 'sentry-deployed': out.push('sentry-deployed'); break;
    case 'sentry-empty': out.push('sentry-empty'); break;
    case 'crossbow-empty': out.push('crossbow-empty'); break;
    case 'beacon': if (!event.lit && event.progress > 0) out.push('beacon'); break;
    case 'ending-step': out.push(`ending-step:${event.step}`); break;
    default: break;
  }
  return out;
}

export type TriggerRef = { readonly line: GuideLine; readonly delay: number };

/** 'done:intro+6' → { key: 'done:intro', delay: 6 }. */
export function parseTrigger(trigger: string): { key: string; delay: number } {
  const plus = trigger.lastIndexOf('+');
  if (plus < 0) return { key: trigger, delay: 0 };
  return { key: trigger.slice(0, plus), delay: Number(trigger.slice(plus + 1)) };
}

/** Trigger key → the lines it can start (with their delays). */
export const TRIGGERS: ReadonlyMap<string, readonly TriggerRef[]> = (() => {
  const map = new Map<string, TriggerRef[]>();
  for (const line of LINES) {
    for (const trigger of line.on) {
      const { key, delay } = parseTrigger(trigger);
      let list = map.get(key);
      if (!list) map.set(key, list = []);
      list.push({ line, delay });
    }
  }
  return map;
})();

export const lineById = (id: string): GuideLine | undefined => LINES.find((line) => line.id === id);

/** Seconds a queued line may wait (its ttl, capped). */
export const lineTtl = (line: GuideLine): number => Math.min(MAX_TTL, line.ttl ?? DEFAULT_TTL);

/** Estimated spoken length (s) of a line whose clip is not available. */
export function estimateSeconds(text: string): number {
  const words = text.trim().split(/\s+/).length;
  return Math.round((0.6 + words / WORDS_PER_SECOND) * 10) / 10;
}

/**
 * Whether a toast matches one of a line's patterns: 'key:<k>' compares the
 * ToastSystem's message key; any other pattern is looked for in the title and body.
 */
export function toastMatches(patterns: readonly string[] | undefined, title: string, body: string, key: string): boolean {
  if (!patterns) return false;
  for (let i = 0; i < patterns.length; i++) {
    const pattern = patterns[i];
    if (pattern.startsWith('key:')) {
      if (key === pattern.slice(4)) return true;
    } else if (title.includes(pattern) || body.includes(pattern)) {
      return true;
    }
  }
  return false;
}

// ─── GameState.guide: comma-separated ids spoken this journey ───

/** Whether `id` is in the comma-separated list (no allocation). */
export function hasSpoken(list: string, id: string): boolean {
  let from = 0;
  for (;;) {
    const at = list.indexOf(id, from);
    if (at < 0) return false;
    const end = at + id.length;
    if ((at === 0 || list.charCodeAt(at - 1) === 44) && (end === list.length || list.charCodeAt(end) === 44)) return true;
    from = end;
  }
}

export const addSpoken = (list: string, id: string): string =>
  (hasSpoken(list, id) ? list : list ? `${list},${id}` : id);

/** The list without `id` (a line cut early is spoken again later). */
export const removeSpoken = (list: string, id: string): string =>
  (hasSpoken(list, id) ? list.split(',').filter((entry) => entry !== id).join(',') : list);

// ─── Voice clips ───

/** The Drawcall speech request for a line (the input `speech()` receives): the words only, never the hint. */
export const speechInput = (line: GuideLine) => ({ text: line.text, voice: VOICE.voice, style: VOICE.style });

/** Asset-manifest id of a line's clip. */
export const clipId = (id: string) => `voice-${id}`;

/** Batch number (1-based) of the line at `index` on the voice-prep page. */
export const prepBatchOf = (index: number) => Math.floor(index / PREP_BATCH) + 1;
export const PREP_BATCHES = Math.ceil(LINES.length / PREP_BATCH);
